import { createServer } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_FILE = path.join(__dirname, 'data', 'books.json');
const PUBLIC_DIR = path.join(__dirname, 'public');
const PORT = process.env.PORT || 3000;

async function loadBooks() {
  if (!existsSync(DATA_FILE)) return [];
  const raw = await readFile(DATA_FILE, 'utf8');
  return raw.trim() ? JSON.parse(raw) : [];
}

async function saveBooks(books) {
  await mkdir(path.dirname(DATA_FILE), { recursive: true });
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2));
}

function sendJson(res, status, body) {
  const data = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(data),
  });
  res.end(data);
}

async function readBody(req) {
  const chunks = [];
  for await (const chunk of req) chunks.push(chunk);
  const raw = Buffer.concat(chunks).toString('utf8');
  return raw ? JSON.parse(raw) : {};
}

const MIME = {
  '.html': 'text/html',
  '.css': 'text/css',
  '.js': 'application/javascript',
};

async function serveStatic(res, filePath) {
  try {
    const data = await readFile(filePath);
    const ext = path.extname(filePath);
    res.writeHead(200, { 'Content-Type': MIME[ext] || 'application/octet-stream' });
    res.end(data);
  } catch {
    res.writeHead(404);
    res.end('Not found');
  }
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const { pathname } = url;

  // --- API routes ---
  if (pathname === '/api/books' && req.method === 'GET') {
    return sendJson(res, 200, await loadBooks());
  }

  if (pathname === '/api/books' && req.method === 'POST') {
    const body = await readBody(req);
    if (!body.title || !body.title.trim()) {
      return sendJson(res, 400, { error: 'Title is required' });
    }
    const book = {
      id: randomUUID(),
      title: body.title.trim(),
      author: (body.author || '').trim(),
      notes: (body.notes || '').trim(),
      status: 'reading',
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    const books = await loadBooks();
    books.push(book);
    await saveBooks(books);
    return sendJson(res, 201, book);
  }

  const bookMatch = pathname.match(/^\/api\/books\/([^/]+)$/);
  if (bookMatch && req.method === 'GET') {
    const books = await loadBooks();
    const book = books.find((b) => b.id === bookMatch[1]);
    if (!book) return sendJson(res, 404, { error: 'Book not found' });
    return sendJson(res, 200, book);
  }

  if (bookMatch && req.method === 'PATCH') {
    const body = await readBody(req);
    const books = await loadBooks();
    const book = books.find((b) => b.id === bookMatch[1]);
    if (!book) return sendJson(res, 404, { error: 'Book not found' });

    if (typeof body.title === 'string') book.title = body.title.trim();
    if (typeof body.author === 'string') book.author = body.author.trim();
    if (typeof body.notes === 'string') book.notes = body.notes.trim();
    if (body.status === 'finished' && book.status !== 'finished') {
      book.status = 'finished';
      book.finishedAt = new Date().toISOString();
    } else if (body.status === 'reading' && book.status !== 'reading') {
      book.status = 'reading';
      book.finishedAt = null;
    }

    await saveBooks(books);
    return sendJson(res, 200, book);
  }

  if (bookMatch && req.method === 'DELETE') {
    const books = await loadBooks();
    const idx = books.findIndex((b) => b.id === bookMatch[1]);
    if (idx === -1) return sendJson(res, 404, { error: 'Book not found' });
    books.splice(idx, 1);
    await saveBooks(books);
    return sendJson(res, 204, null);
  }

  // --- Static / page routes ---
  if (pathname === '/' || pathname === '/index.html') {
    return serveStatic(res, path.join(PUBLIC_DIR, 'index.html'));
  }

  if (/^\/book\/[^/]+$/.test(pathname)) {
