:root {
  color-scheme: light dark;
  --bg: #fafaf9;
  --surface: #ffffff;
  --border: #e5e3df;
  --text: #1f1d1a;
  --muted: #6b6862;
  --accent: #5a5346;
  --accent-text: #ffffff;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

.container {
  max-width: 720px;
  margin: 0 auto;
  padding: 32px 20px 80px;
}

h1 {
  font-size: 1.6rem;
  margin: 0 0 4px;
}

.subtitle {
  color: var(--muted);
  margin: 0 0 28px;
}

header.page-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

button, input, textarea {
  font: inherit;
}

button {
  cursor: pointer;
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 8px;
  padding: 8px 14px;
  color: var(--text);
}

button.primary {
  background: var(--accent);
  color: var(--accent-text);
  border-color: var(--accent);
}

button:hover {
  filter: brightness(0.97);
}

section.section {
  margin-bottom: 32px;
}

section.section h2 {
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted);
  margin: 0 0 12px;
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.book-card {
  display: block;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px 16px;
  text-decoration: none;
  color: var(--text);
}

.book-card:hover {
  border-color: var(--accent);
}

.book-card .title {
  font-weight: 600;
}

.book-card .author {
  color: var(--muted);
  font-size: 0.92rem;
}

.empty {
  color: var(--muted);
  font-size: 0.95rem;
  padding: 8px 0;
}

form.add-form {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

form.add-form label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.85rem;
  color: var(--muted);
}

form.add-form input,
form.add-form textarea {
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg);
  color: var(--text);
}

form.add-form textarea {
  resize: vertical;
  min-height: 60px;
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.back-link {
  display: inline-block;
  margin-bottom: 20px;
  color: var(--muted);
  text-decoration: none;
}

.back-link:hover {
  color: var(--text);
}

.book-detail .title {
  font-size: 1.5rem;
  margin: 0 0 4px;
}

.book-detail .author {
  color: var(--muted);
  margin: 0 0 20px;
}

.status-badge {
  display: inline-block;
  font-size: 0.75rem;
  padding: 3px 9px;
  border-radius: 999px;
  background: var(--border);
  color: var(--muted);
  margin-bottom: 20px;
}

.status-badge.finished {
  background: #dfe9df;
  color: #345c34;
}

.notes-block label {
  display: block;
  font-size: 0.85rem;
  color: var(--muted);
  margin-bottom: 6px;
}

.notes-block textarea {
  width: 100%;
  min-height: 160px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
  color: var(--text);
}

.detail-actions {
  display: flex;
  gap: 8px;
  margin-top: 16px;
  flex-wrap: wrap;
}

.share-row {
  margin-top: 24px;
  display: flex;
  gap: 8px;
  align-items: center;
}

.share-row input {
  flex: 1;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--surface);
  color: var(--muted);
}

.hint {
  font-size: 0.85rem;
  color: var(--muted);
  margin-top: 6px;
}

.error {
  color: #a33;
  font-size: 0.9rem;
}

