const readingList = document.getElementById('reading-list');
const finishedList = document.getElementById('finished-list');
const readingEmpty = document.getElementById('reading-empty');
const finishedEmpty = document.getElementById('finished-empty');
const addToggle = document.getElementById('add-toggle');
const addForm = document.getElementById('add-form');
const cancelAdd = document.getElementById('cancel-add');
const addError = document.getElementById('add-error');

function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
}

function renderBookCard(book) {
  const li = document.createElement('li');
  li.innerHTML = `
    <a class="book-card" href="/book/${book.id}">
      <div class="title">${escapeHtml(book.title)}</div>
      <div class="author">${escapeHtml(book.author || 'Unknown author')}</div>
    </a>
  `;
  return li;
}

async function loadBooks() {
  const res = await fetch('/api/books');
  const books = await res.json();

  readingList.innerHTML = '';
  finishedList.innerHTML = '';

  const reading = books.filter((b) => b.status !== 'finished');
  const finished = books.filter((b) => b.status === 'finished');

  reading.forEach((b) => readingList.appendChild(renderBookCard(b)));
  finished.forEach((b) => finishedList.appendChild(renderBookCard(b)));

  readingEmpty.hidden = reading.length > 0;
  finishedEmpty.hidden = finished.length > 0;
}

addToggle.addEventListener('click', () => {
  addForm.hidden = !addForm.hidden;
});

cancelAdd.addEventListener('click', () => {
  addForm.reset();
  addForm.hidden = true;
  addError.hidden = true;
});

addForm.addEventListener('submit', async (e) => {
  e.preventDefault();
  addError.hidden = true;
  const formData = new FormData(addForm);
  const body = {
    title: formData.get('title'),
    author: formData.get('author'),
    notes: formData.get('notes'),
  };

  const res = await fetch('/api/books', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });

  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    addError.textContent = err.error || 'Could not add book.';
    addError.hidden = false;
    return;
  }

  addForm.reset();
  addForm.hidden = true;
  await loadBooks();
});

loadBooks();

