const container = document.getElementById('book-detail');
const id = window.location.pathname.split('/').filter(Boolean).pop();

function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
}

async function loadBook() {
  const res = await fetch(`/api/books/${id}`);
  if (!res.ok) {
    container.innerHTML = '<p class="empty">Book not found.</p>';
    return;
  }
  const book = await res.json();
  render(book);
}

function render(book) {
  const isFinished = book.status === 'finished';
  const shareUrl = window.location.href;

  container.innerHTML = `
    <span class="status-badge ${isFinished ? 'finished' : ''}">${isFinished ? 'Finished' : 'Currently reading'}</span>
    <h1 class="title">${escapeHtml(book.title)}</h1>
    <p class="author">${escapeHtml(book.author || 'Unknown author')}</p>

    <div class="notes-block">
      <label for="notes">Notes</label>
      <textarea id="notes" placeholder="Add your notes...">${escapeHtml(book.notes || '')}</textarea>
    </div>

    <div class="detail-actions">
      <button id="save-notes">Save notes</button>
      ${isFinished
        ? '<button id="toggle-status">Mark as still reading</button>'
        : '<button id="toggle-status" class="primary">Mark as finished</button>'}
    </div>

    <div class="share-row">
      <input type="text" readonly value="${escapeHtml(shareUrl)}" id="share-url" />
      <button id="copy-link">Copy link</button>
    </div>
    <p class="hint" id="save-hint" hidden>Saved.</p>
  `;

  document.getElementById('save-notes').addEventListener('click', async () => {
    const notes = document.getElementById('notes').value;
    await fetch(`/api/books/${id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ notes }),
    });
    const hint = document.getElementById('save-hint');
    hint.hidden = false;
    setTimeout(() => { hint.hidden = true; }, 1500);
  });

  document.getElementById('toggle-status').addEventListener('click', async () => {
    const newStatus = isFinished ? 'reading' : 'finished';
    const res = await fetch(`/api/books/${id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: newStatus }),
    });
    const updated = await res.json();
    render(updated);
  });

  document.getElementById('copy-link').addEventListener('click', async () => {
    const input = document.getElementById('share-url');
    input.select();
    try {
      await navigator.clipboard.writeText(shareUrl);
    } catch {
      document.execCommand('copy');
    }
  });
}

loadBook();

